```sql
SELECT degrees(ST_Azimuth(
    (SELECT geometry FROM pois WHERE poi_name ILIKE '%Longfellow Arboretum%' LIMIT 1),
    (SELECT geometry FROM pois WHERE amenity = 'stadium' AND ST_DWithin(pois.geometry::geography, (SELECT geometry FROM pois WHERE poi_name ILIKE '%Longfellow Arboretum%' LIMIT 1)::geography, 10000) ORDER BY pois.geometry <-> (SELECT geometry FROM pois WHERE poi_name ILIKE '%Longfellow Arboretum%' LIMIT 1) LIMIT 1
)) AS bearing_degrees;
```

```sql
SELECT degrees(ST_Azimuth(
    (SELECT geometry FROM pois WHERE poi_name ILIKE '%Hickory Grove Riverfront%' LIMIT 1),
    (SELECT geometry FROM parks WHERE park_name ILIKE '%theme park%' LIMIT 1)
)) AS direction_degrees;
```

```sql
SELECT degrees(ST_Azimuth(
    (SELECT geometry FROM pois WHERE poi_name ILIKE '%Cal, Sr.\'s Yard%' LIMIT 1),
    (SELECT geometry FROM pois WHERE amenity = 'fast_food' ORDER BY (SELECT geometry FROM pois WHERE poi_name ILIKE '%Cal, Sr.\'s Yard%' LIMIT 1) <-> geometry LIMIT 1)
)) AS direction_degrees;
```

```sql
SELECT degrees(ST_Azimuth(p1.geometry, p2.geometry)) AS direction_degrees
FROM (
    SELECT geometry FROM pois WHERE poi_name ILIKE '%Randall Football Stadium%' LIMIT 1
) AS p1,
(
    SELECT geometry FROM pois WHERE tourism = 'aquarium' LIMIT 1
) AS p2;
```

```sql
SELECT degrees(ST_Azimuth(
    (SELECT geometry FROM pois WHERE poi_name ILIKE '%ABQ BioPark%' LIMIT 1),
    (SELECT geometry FROM pois WHERE amenity = 'hospital' AND addr_city ILIKE '%Albuquerque%' ORDER BY pois.geometry <-> (SELECT geometry FROM pois WHERE poi_name ILIKE '%ABQ BioPark%' LIMIT 1) LIMIT 1)
)) AS direction_degrees;
```
